begin;

insert into role_profiles (external_id, isco_code, title, alt_titles, description) values
  ('http://data.europa.eu/esco/occupation/9f508305-80ce-4111-8722-f2c9b4a44890', '1223.1', 'product manager', array['product marketing manager','product developer','research and development manager','product development manager','sports product engineer']::text[], 'Product managers are responsible for managing the lifecycle of a product. They research and develop new products in addition to managing existing ones through market research and strategic planning. Product managers perform marketing and planning activities to increase profits.'),
  ('http://data.europa.eu/esco/occupation/d3edb8f8-3a06-47a0-8fb9-9b212c006aa2', '2511.3', 'data analyst', array['data warehousing analyst','data warehouse analyst','business data analyst','data storage analyst']::text[], 'Data analysts import, inspect, clean, transform, validate, model, or interpret collections of data with regard to the business goals of the company. They ensure that the data sources and repositories provide consistent and reliable data. Data analysts use different algorithms and IT tools as demanded by the situation and the current data. They might prepare reports in the form of visualisations such as graphs, charts, and dashboards.'),
  ('http://data.europa.eu/esco/occupation/258e46f9-0075-4a2e-adae-1ff0477e0f30', '2511.4', 'data scientist', array['research data scientist','data expert','data research scientist']::text[], 'Data scientists find and interpret rich data sources, manage large amounts of data, merge data sources, ensure consistency of data-sets, and create visualisations to aid in understanding data. They build mathematical models using data, present and communicate data insights and findings to specialists and scientists in their team and if required, to a non-expert audience, and recommend ways to apply the data.'),
  ('http://data.europa.eu/esco/occupation/f2b15a0e-e65a-438a-affb-29b9d50b77d1', '2512.4', 'software developer', array['battery software developer','application developer','application programmer','solutions developer','programmer','software specialist','software developers','applications engineer','soft developer','application software developer']::text[], 'Software developers implement or program all kinds of software systems based on specifications and designs by using programming languages, tools, and platforms.'),
  ('http://data.europa.eu/esco/occupation/60082a99-d8ef-4e84-9290-78902681b6ed', '2421.1', 'business analyst', array['standardisation expert','business strategy analyst','standardization expert','business development analyst','business strategy consultant','management consultant','standardisation manager','organisational developer']::text[], 'Business analysts research and understand the strategic position of businesses and companies in relation to their markets and their stakeholders. They analyse and present their views on how the company, from many perspectives, can improve its strategic position and internal corporate structure. They assess needs for change, communication methods, technology, IT tools, new standards and certifications.'),
  ('http://data.europa.eu/esco/occupation/96e20037-0a25-4bf6-a25e-808d1605d890', '2513.3', 'user interface designer', array['accessibility designer','user interface designers','UI designer']::text[], 'User interface designers are in charge of designing user interfaces for applications and systems. They perform layout, graphics and dialogues design activities as well as adaptation activities.'),
  ('http://data.europa.eu/esco/occupation/bea99fea-0383-4c63-b944-70d4799de2c5', '1219.6', 'project manager', array['project coordinator','project leader','special project manager','project expediter','senior project manager','project director','projects manager']::text[], 'Project managers oversee the project on a daily basis and are responsible for delivering high-quality results within the identified objectives and constraints, ensuring the effective use of the allocated resources. They are responsible for risk and issue management, project communication and stakeholder management. Project managers perform the activities of planning, organising, securing, monitoring and managing the resources and work necessary to deliver specific project goals and objectives in an effective and efficient way.'),
  ('http://data.europa.eu/esco/occupation/6fcf4638-e7c7-4978-9302-9a7b63a3d57c', '1221.3.2', 'marketing manager', array['advertising sales manager','promotions manager','marketing executive','telemarketing manager','product marketing manager','market manager','sales and marketing manager','marketing and promotions manager','market development manager','marketing director']::text[], 'Marketing managers carry out the implementation of efforts related to the marketing operations in a company. They develop marketing strategies and plans by detailing cost and resources needed. They analyse the profitability of these plans, develop pricing strategies, and strive to raise awareness on products and companies among targeted customers.'),
  ('http://data.europa.eu/esco/occupation/a7594892-ff23-4e2a-aedf-2f967ebca15c', '1221.3.2.1', 'sales manager', array['group sales manager','sales coordinator','area sales manager','inside sales manager','sales director','international sales manage','sales commercial manager','sales executive']::text[], 'Sales managers develop sales and targeting strategies for a company. They manage sales teams, allocate sales resources based on the plans, prioritise and follow up on critical leads, develop sales pitches and adjust them over time, and maintain a sales platform to track all leads and sales.'),
  ('http://data.europa.eu/esco/occupation/c6bd511a-d966-4df9-a48e-4f800354f268', '1321.2.3', 'operations manager', array['division operations manager','operations administrator','operations supervisor','operations general manager','operations director','business operations manager']::text[], 'Operations managers plan, oversee and coordinate the daily operations of production of goods and provision of services. They also formulate and implement company policies and plan the use of human resources and materials.'),
  ('http://data.europa.eu/esco/occupation/aaeec9a7-dc57-4485-890c-86b3eef735f9', '3512.1', 'ICT help desk agent', array['IT help desk advisor','ICT service desk agent','ICT help desk advisor','IT help desk agent','IT support technician','ICT helpdesk agent']::text[], 'ICT help desk agents provide technical assistance to computer users, answer questions or solve computer problems for clients via telephone or electronically. They provide assistance concerning the use of computer hardware and software.')
on conflict (external_id) do update set title = excluded.title, alt_titles = excluded.alt_titles, description = excluded.description, isco_code = excluded.isco_code;

